  const measure = performance.getEntriesByName(label)[0];
  if (measure.duration > 20) console.warn(`${label} exceeded: ${measure.duration}ms`);
  return result;
}

measureJSExecution('init-scripts', () => initializeApp());
measureJSExecution('event-handler', () => handleUserClick());
```

**Типичная ошибка:** Рассмотрение бюджета как одного пула вместо распределения по фазам жизненного цикла.

